"""Statement-first onboarding using the established Everyday design system."""
STATEMENTS_CSS = r'''
.statement-home{max-width:1080px;margin:auto}.statement-welcome{display:grid;grid-template-columns:minmax(0,1fr) 140px;align-items:center;gap:24px;padding:36px;border:1px solid var(--line);border-radius:26px;background:linear-gradient(110deg,var(--panel),var(--panel2))}.statement-welcome h1{font-size:clamp(30px,4vw,46px);letter-spacing:-.05em;line-height:1.15;margin:0 0 14px}.statement-welcome p{max-width:560px;color:var(--muted);font-size:15px;margin-bottom:22px}.statement-companion{width:130px;height:130px;object-fit:contain;animation:friday-float 8s ease-in-out infinite}.statement-home .money-summary{grid-template-columns:repeat(3,minmax(0,1fr))}.statement-home .money-stat{padding:22px}.statement-home .money-stat strong{font-size:24px}.statement-subtle{color:var(--muted);font-size:13px;line-height:1.7}.statement-card{padding:28px;border:1px solid var(--line);background:var(--panel);border-radius:22px;margin:22px 0}.statement-card h2{font-size:23px;letter-spacing:-.035em;margin-bottom:10px}.statement-card p{color:var(--muted);font-size:14px}.statement-path{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0;font-size:12px;color:var(--muted)}.statement-path span{border-radius:24px;padding:8px 13px;background:var(--panel2);border:1px solid var(--line)}.statement-form{display:grid;gap:18px;max-width:720px}.statement-form label{display:grid;gap:8px}.statement-form label.statement-check{display:flex;gap:10px;align-items:flex-start}.statement-form input,.statement-form select{width:100%}.statement-form .statement-check input{width:18px;margin-top:4px}.statement-form .form-grid{margin:0}.statement-error{color:var(--red)!important}.statement-success{color:var(--cyan)!important}.statement-chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.statement-bar-row{margin:18px 0}.statement-bar-title{display:flex;justify-content:space-between;gap:10px;font-size:13px;margin:0 0 8px}.statement-bar-track{height:12px;border-radius:8px;background:var(--panel2);overflow:hidden}.statement-bar-fill{height:100%;border-radius:8px;background:#a69cd8}.statement-bar-fill.income{background:#65a88c}.statement-bar-fill.outgoing{background:#e9a38c}.statement-chart-note{font-size:12px!important}.statement-review-scroll{overflow:auto;max-height:520px;border:1px solid var(--line);border-radius:14px;margin:20px 0}.statement-table{border-collapse:collapse;width:100%;font-size:12px}.statement-table th,.statement-table td{padding:12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}.statement-table th{position:sticky;top:0;background:var(--panel2);z-index:1;white-space:nowrap}.statement-table td{overflow-wrap:anywhere}.statement-table select{min-width:115px;max-width:160px;font-size:12px;padding:8px;min-height:44px}.statement-table .statement-description{min-width:150px;max-width:220px}.statement-account-badge{max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.statement-profile-value{overflow-wrap:anywhere;font-size:18px!important;color:var(--ink)!important}.statement-next{border-left:4px solid #a69cd8;padding-left:18px}.statement-empty{padding:26px;border:1px dashed var(--line);border-radius:20px;background:var(--panel);margin:24px 0}.statement-consent-details{border:1px solid var(--line);border-radius:14px;padding:15px;margin:16px 0}.statement-consent-details summary{cursor:pointer;font-size:13px}.statement-coach .everyday-assistant{max-width:780px;margin:auto;width:100%}.statement-coach .friday-chat-log{max-height:360px}.statement-coach .friday-chat-consent{color:inherit}.statement-coach .friday-prepare-button{display:none}.statement-coach .friday-command-actions{grid-template-columns:1fr}.statement-coach .friday-chat-tools button:first-child{display:none}.statement-profile .buddy-profile{margin-top:20px}.statement-imports details{margin:14px 0}.statement-imports summary{cursor:pointer;min-height:44px;display:flex;align-items:center}.statement-warning-list{padding-left:20px;line-height:1.8;color:var(--amber);font-size:13px}.statement-home-nav{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}.statement-home-nav button{font-size:13px}.statement-only-home{display:block!important}.statement-status{min-height:26px;line-height:1.65;font-size:13px}.statement-status[aria-busy=true]{color:var(--blue)}
@media(max-width:760px){.statement-welcome{grid-template-columns:1fr 74px;padding:24px;gap:12px}.statement-companion{width:74px;height:74px}.statement-welcome h1{font-size:30px}.statement-chart-grid{grid-template-columns:1fr}.statement-home .money-summary{grid-template-columns:1fr}.statement-home .money-stat{padding:18px}.statement-card{padding:20px}.statement-home .money-stat strong{font-size:23px}.statement-form .form-grid{grid-template-columns:1fr}.statement-account-badge{max-width:120px}.statement-table th,.statement-table td{padding:10px}}
'''

